class Solution {
public:
    int getDecimalValue(ListNode* head) {
        int ans = 0;
        ListNode* cur = head;
        while (cur != nullptr) {
            ans = (ans << 1) | cur->val;
            cur = cur->next;
        }
        return ans;
    }
};

class Solution {
    public int getDecimalValue(ListNode head) {
        int ans = 0;
        ListNode cur = head;
        while (cur != null) {
            ans = (ans << 1) | cur.val;
            cur = cur.next;
        }
        return ans;
    }
}

var getDecimalValue = function(head) {
    let ans = 0;
    let cur = head;
    while (cur !== null) {
        ans = (ans << 1) | cur.val;
        cur = cur.next;
    }
    return ans;
};
